placeOrder=async function(){try{const items=Object.entries(cart).map(([product_id,quantity])=>({product_id,quantity:+quantity}));const body={p_store_name:$('cs').value,p_responsible_name:$('cn').value,p_phone:$('cp').value,p_document:p?.document||'',p_cep:$('cc').value,p_street:$('ct').value,p_address_number:$('cno').value,p_district:$('cbairro').value,p_complement:'',p_city:$('cci').value,p_state:$('cu').value,p_shipping_method:$('cm').value,p_payment_method:'pix',p_coupon_code:'',p_items:items};$('confirmOrderBtn').disabled=true;$('confirmOrderBtn').textContent='Criando pedido...';const result=await api('/rest/v1/rpc/create_shop_order_v4',{method:'POST',body:JSON.stringify(body)}),o=Array.isArray(result)?result[0]:result;cart={};localStorage.setItem(CK,'{}');closeM('checkout');await Promise.all([loadCat(),loadOrders(),loadCheckoutSettings()]);renderPixResult(o);$('pixModal').classList.add('on')}catch(e){toast(e.message)}finally{if($('confirmOrderBtn')){$('confirmOrderBtn').disabled=false;$('confirmOrderBtn').textContent='Confirmar pedido'}}};
function renderPixResult(o){const total=+o?.total||0;$('pixOrderInfo').innerHTML=`<div class="row"><div><b>Pedido #${esc(o?.order_number||'')}</b><small>Pagamento pendente • reserva por 24h</small></div><div class="pixAmount">${money(total)}</div></div>`;if(checkoutSettings?.pix_key){$('pixConfigured').innerHTML=`<div class="pixKeyBox"><small>Recebedor</small><b>${esc(checkoutSettings.pix_receiver||'Shop Importadora')}</b></div><div class="pixKeyBox"><small>Chave PIX ${checkoutSettings.pix_key_type?`• ${esc(checkoutSettings.pix_key_type)}`:''}</small><b id="pixKeyText">${esc(checkoutSettings.pix_key)}</b></div><button class="btn red" onclick="copyPixKey()">Copiar chave PIX</button><small class="mut">Após o pagamento, a confirmação poderá ser atualizada no seu pedido.</small>`}else $('pixConfigured').innerHTML='<div class="pixNotConfigured">Pedido criado. A chave PIX ainda não foi configurada pelo administrador. Entre em contato com a Shop Importadora para o pagamento.</div>'}
window.copyPixKey=async function(){try{await navigator.clipboard.writeText(checkoutSettings.pix_key);toast('Chave PIX copiada')}catch{toast('Copie a chave PIX exibida na tela')}};

let _clientLoadAll=loadAll;loadAll=async function(){await _clientLoadAll();await loadCheckoutSettings();fillFilters();renderProducts()};

adminPage=function(x){document.querySelectorAll('.ap').forEach(e=>e.classList.remove('on'));$('a-'+x)?.classList.add('on');document.querySelectorAll('.nav button').forEach(e=>e.classList.toggle('on',e.dataset.p===x));$('adminTitle').textContent=({overview:'Dashboard',products:'Produtos',orders:'Pedidos',customers:'Clientes',notifications:'Notificações',settings:'Configurações'})[x]||'Central do Administrador';if(innerWidth<900)side(false);if(x==='overview')loadSalesDashboard();if(x==='settings')renderCheckoutSettingsAdmin()};
async function loadSalesDashboard(days=30){if(!adm.ok)return;try{adminSales=await api('/rest/v1/rpc/get_admin_sales_dashboard_v1',{method:'POST',body:JSON.stringify({p_days:+days||30})})||{};renderSalesDashboard()}catch(e){console.warn(e.message)}}
window.loadSalesDashboard=loadSalesDashboard;
async function loadAdminExtras(){await Promise.all([loadSalesDashboard(+$('dashPeriod')?.value||30),loadCheckoutSettings()]);renderCheckoutSettingsAdmin()}
loadAdmin=async function(){await _loadAdminV28();await loadAdminExtras()};
renderAdmin=function(){_renderAdminV28();renderSalesDashboard();renderCheckoutSettingsAdmin()};
function renderSalesDashboard(){if(!$('a-overview'))return;const d=adminSales||{},daily=d.daily_sales||[],max=Math.max(...daily.map(x=>+x.total||0),1),topP=d.top_products||[],topC=d.top_customers||[];$('a-overview').innerHTML=`<div class="dashHead"><div><div class="mut">GESTÃO DA OPERAÇÃO</div><h2>Dashboard de vendas</h2><p class="mut">Indicadores reais dos pedidos gravados no banco.</p></div><select id="dashPeriod" class="field dashPeriod" onchange="loadSalesDashboard(this.value)"><option value="7" ${d.period_days==7?'selected':''}>Últimos 7 dias</option><option value="30" ${!d.period_days||d.period_days==30?'selected':''}>Últimos 30 dias</option><option value="90" ${d.period_days==90?'selected':''}>Últimos 90 dias</option><option value="365" ${d.period_days==365?'selected':''}>Último ano</option></select></div><div class="dashKpis"><div class="dashKpi"><small>Vendas no período</small><strong>${money(d.gross_sales||0)}</strong><em>${d.orders||0} pedidos</em></div><div class="dashKpi"><small>Receita recebida</small><strong>${money(d.paid_revenue||0)}</strong><em>${d.paid_orders||0} pedidos pagos</em></div><div class="dashKpi"><small>Ticket médio</small><strong>${money(d.avg_ticket||0)}</strong><em>${d.customers||0} clientes compradores</em></div><div class="dashKpi"><small>Saúde do catálogo</small><strong>${d.low_stock||0}</strong><em>itens com estoque baixo</em></div></div><div class="dashGrid"><div class="dashBox"><h3>Evolução das vendas</h3><div class="salesBars">${daily.length?daily.map(x=>`<div class="salesBar" style="height:${Math.max(5,(+x.total||0)/max*100)}%" data-tip="${new Date(x.sales_date+'T12:00:00').toLocaleDateString('pt-BR')} • ${money(x.total)}"></div>`).join(''):'<div class="mut">Ainda não há vendas suficientes neste período.</div>'}</div></div><div class="dashBox"><h3>Qualidade do catálogo</h3><div class="healthGrid"><div class="healthCard"><strong>${d.low_stock||0}</strong><small>Estoque crítico</small></div><div class="healthCard"><strong class="adminImageWarn">${d.missing_images||0}</strong><small>Produtos sem foto</small></div></div></div><div class="dashBox"><h3>Produtos mais vendidos</h3><div class="dashList">${topP.length?topP.map(x=>`<div class="dashItem"><div><b>${esc(x.product_name)}</b><small>${x.quantity} unidades</small></div><strong>${money(x.sales)}</strong></div>`).join(''):'<div class="mut">Sem dados no período.</div>'}</div></div><div class="dashBox"><h3>Clientes que mais compram</h3><div class="dashList">${topC.length?topC.map(x=>`<div class="dashItem"><div><b>${esc(x.store_name||'Lojista')}</b><small>${x.orders} pedidos</small></div><strong>${money(x.total)}</strong></div>`).join(''):'<div class="mut">Sem dados no período.</div>'}</div></div></div>`}
function renderCheckoutSettingsAdmin(){if(!$('setPixKey'))return;setv('setPixType',checkoutSettings.pix_key_type);setv('setPixKey',checkoutSettings.pix_key);setv('setPixReceiver',checkoutSettings.pix_receiver);setv('setFreight',checkoutSettings.default_freight);setv('setFreeFreight',checkoutSettings.free_shipping_threshold);setv('setMinimum',checkoutSettings.minimum_order);setv('setAddress',checkoutSettings.store_address)}
window.saveCheckoutSettings=async function(){try{await api('/rest/v1/rpc/admin_update_checkout_settings_v1',{method:'POST',body:JSON.stringify({p_pix_key:val('setPixKey'),p_pix_key_type:val('setPixType'),p_pix_receiver:val('setPixReceiver'),p_default_freight:+val('setFreight')||0,p_free_shipping_threshold:+val('setFreeFreight')||0,p_minimum_order:+val('setMinimum')||0,p_store_address:val('setAddress')})});await loadCheckoutSettings();renderCheckoutSettingsAdmin();toast('Configurações salvas')}catch(e){toast(e.message)}};

editProduct=function(id=''){const x=id?adm.products.find(p=>p.id===id):{};$('pi').value=x?.id||'';$('pt').textContent=x?.id?'Editar produto':'Novo produto';setv('psku',x?.sku);setv('pn',x?.name);setv('pb',x?.brand);setv('pp',x?.sale_price);setv('pr',x?.reference_price);setv('pco',x?.cost_price);setv('pst',x?.stock_qty??0);setv('pmin',x?.min_per_customer||1);setv('pimg',x?.image_url);setv('pwarranty',x?.warranty_text);setv('pgallery',(x?.gallery_urls||[]).join('\n'));setv('pd',x?.description);setv('pspecs',x?.specs&&typeof x.specs==='object'?Object.entries(x.specs).map(([k,v])=>`${k}: ${v}`).join('\n'):'');$('pcat').innerHTML=adm.categories.map(c=>`<option value="${c.id}" ${x?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('');let ts=tiersOf(x);if(!ts.length&&x?.sale_price)ts=[{min:1,price:+x.sale_price}];for(let i=1;i<=4;i++){setv('tierMin'+i,ts[i-1]?.min||'');setv('tierPrice'+i,ts[i-1]?.price||'')}if(!id&&!$('tierMin1').value)$('tierMin1').value=1;$('productModal').classList.add('on')};
function parseSpecs(){const o={};val('pspecs').split(/\n+/).forEach(line=>{const i=line.indexOf(':');if(i>0){const k=line.slice(0,i).trim(),v=line.slice(i+1).trim();if(k&&v)o[k]=v}});return o}
function readTiers(){const a=[];for(let i=1;i<=4;i++){const min=+$('tierMin'+i).value,price=+$('tierPrice'+i).value;if(min>0&&price>0)a.push({min_qty:min,price})}return a.sort((a,b)=>a.min_qty-b.min_qty)}
saveProduct=async function(){try{const tiers=readTiers(),gallery=val('pgallery').split(/\n+/).map(x=>x.trim()).filter(Boolean),existing=adm.products.find(x=>x.id===val('pi')),d={id:val('pi')||null,sku:val('psku'),name:val('pn'),category_id:val('pcat'),mode:'ready',sale_price:val('pp'),reference_price:val('pr'),cost_price:val('pco'),stock_qty:val('pst'),min_per_customer:val('pmin'),max_per_customer:null,brand:val('pb'),badge:existing?.badge||'',image_url:val('pimg'),warranty_text:val('pwarranty'),description:val('pd'),specs:parseSpecs(),price_tiers:tiers,gallery_urls:gallery,featured:existing?.featured||false,active:existing?.active!==false,unit_label:existing?.unit_label||'un.'};if(!d.sku||!d.name)return toast('Informe SKU e nome');if(!tiers.length&&+d.sale_price>0)d.price_tiers=[{min_qty:+d.min_per_customer||1,price:+d.sale_price}];await api('/rest/v1/rpc/admin_upsert_product_v2',{method:'POST',body:JSON.stringify({p_data:d})});closeM('productModal');await Promise.all([loadCat(),loadAdmin()]);toast('Produto salvo com preço e galeria')}catch(e){toast(e.message)}};

setTimeout(()=>{fillFilters();renderProducts();loadCheckoutSettings().then(()=>{renderCheckoutSettingsAdmin();if(adm.ok)loadSalesDashboard()})},0);

/* Persistent cart controls on product cards V5 */
(()=>{
function compactBounds(x){const min=Math.max(1,Number(x?.min_per_customer)||1);const stock=Math.max(0,Number(x?.stock_qty)||0);return {min,max:Math.max(min,stock)}}
function saveCartLocal(){localStorage.setItem(CK,JSON.stringify(cart))}
function compactActionHTML(x){const inCart=Math.max(0,Number(cart?.[x.id])||0);const out=Number(x.stock_qty)<=0;if(out)return `<button class="btn" onclick="openProductDetail('${x.id}')">Ver detalhes</button><button class="btn red compactAddBtn" disabled>Sem estoque</button>`;if(!inCart)return `<button class="btn" onclick="openProductDetail('${x.id}')">Ver detalhes</button><button class="btn red compactAddBtn" onclick="addQuickItem('${x.id}',this)">Adicionar</button>`;const {min,max}=compactBounds(x),qty=Math.max(min,Math.min(max,inCart));return `<div class="quickPersistent"><button class="quickStep" onclick="persistentStep('${x.id}',-1,this)" ${qty<=min?'disabled':''}>−</button><input class="quickQtyInput" type="number" min="${min}" max="${max}" step="1" inputmode="numeric" value="${qty}" aria-label="Quantidade" oninput="persistentTyped('${x.id}',this)" onblur="persistentBlur('${x.id}',this)"><button class="quickStep" onclick="persistentStep('${x.id}',1,this)" ${qty>=max?'disabled':''}>+</button></div><button class="quickRemoveInline" onclick="removeQuickItem('${x.id}',this)">Remover do carrinho</button>`}
function compactProductCard(x){const pd=profitData(x),out=+x.stock_qty<=0,brand=x.brand||x.category_name||'Shop Importadora',sku=x.sku||'',tiers=hasRealTiers(x);return `<div class="prod premiumProdCard ${out?'stockOut':''}"><div class="img premiumProdImage" onclick="openProductDetail('${x.id}')">${x.image_url?`<img loading="lazy" src="${esc(x.image_url)}" alt="${esc(x.name)}">`:'<span class="prodNoImage">📦</span>'}${tiers?'<span class="prodTierBadge">ATACADO</span>':''}</div><div class="prodMeta"><span class="prodBrand">${esc(brand)}</span>${sku?`<span class="prodSku">${esc(sku)}</span>`:''}</div><h3 class="prodName" onclick="openProductDetail('${x.id}')">${esc(x.name)}</h3><div class="prodPriceBlock"><small>Preço no atacado</small><div class="price">${money(x.sale_price)}${x.reference_price?`<span class="oldPrice">${money(x.reference_price)}</span>`:''}</div></div><div class="prodInfoRow"><span class="prodStockPill ${out?'out':'ok'}">${out?'Sem estoque':`● ${esc(stockLabel(x))}`}</span>${pd?`<span class="prodProfitPill">+${pd.margin.toFixed(0)}% margem</span>`:''}</div><div class="prodActions compactActions premiumActions" data-product="${x.id}">${compactActionHTML(x)}</div></div>`}
function paintPersistentActions(productId,except=null){document.querySelectorAll('.compactActions[data-product]').forEach(wrap=>{if(wrap===except)return;if(productId&&wrap.dataset.product!==productId)return;const x=cat.find(p=>p.id===wrap.dataset.product);if(x)wrap.innerHTML=compactActionHTML(x)})}
const baseRenderCartPersistent=renderCart;function refreshCartPersistent(productId,except=null){baseRenderCartPersistent();paintPersistentActions(productId,except)}renderCart=function(){baseRenderCartPersistent();paintPersistentActions()};
window.addQuickItem=function(id,button){const x=cat.find(p=>p.id===id);if(!x||+x.stock_qty<=0)return toast('Produto sem estoque');const {min,max}=compactBounds(x),qty=Math.min(min,max);cart[id]=qty;saveCartLocal();renderCart();toast(`${qty} ${qty===1?'unidade adicionada':'unidades adicionadas'} ao carrinho`)};
window.persistentStep=function(id,delta,button){const x=cat.find(p=>p.id===id),wrap=button?.closest('.compactActions');if(!x||!wrap)return;const {min,max}=compactBounds(x),input=wrap.querySelector('.quickQtyInput');const current=Math.floor(Number(input?.value||cart?.[id]||min));const qty=Math.max(min,Math.min(max,current+Number(delta||0)));cart[id]=qty;saveCartLocal();renderCart()};
window.persistentTyped=function(id,input){const x=cat.find(p=>p.id===id),wrap=input?.closest('.compactActions');if(!x||!wrap)return;const {min,max}=compactBounds(x);let n=Math.floor(Number(input.value));if(!Number.isFinite(n)||n<=0)return;if(n>max){n=max;input.value=String(max);toast(`Estoque máximo: ${max}`)}if(n<min)return;cart[id]=n;saveCartLocal();refreshCartPersistent(id,wrap);const minus=wrap.querySelector('.quickStep:first-child'),plus=wrap.querySelector('.quickStep:last-child');if(minus)minus.disabled=n<=min;if(plus)plus.disabled=n>=max};
window.persistentBlur=function(id,input){const x=cat.find(p=>p.id===id),wrap=input?.closest('.compactActions');if(!x||!wrap)return;const {min,max}=compactBounds(x);const requested=Math.floor(Number(input.value));const qty=Math.max(min,Math.min(max,Number.isFinite(requested)&&requested>0?requested:min));input.value=String(qty);cart[id]=qty;saveCartLocal();refreshCartPersistent(id,wrap);const steps=wrap.querySelectorAll('.quickStep');if(steps[0])steps[0].disabled=qty<=min;if(steps[1])steps[1].disabled=qty>=max};
window.removeQuickItem=function(id,button){const x=cat.find(p=>p.id===id);if(!x)return;delete cart[id];saveCartLocal();renderCart();toast('Produto removido do carrinho')};proCard=compactProductCard;card=compactProductCard;window.quickAdd=window.addQuickItem;setTimeout(()=>{try{if($('homeGrid'))$('homeGrid').innerHTML=cat.filter(x=>+x.stock_qty>0).slice(0,4).map(compactProductCard).join('');renderProducts();renderCart()}catch{}},0)})();

/* Product image double tap zoom guard V1 */
(()=>{let lastProductImageTap=0;const isProductImage=e=>e.target?.closest?.('.prod .img,.detailMainImage,.detailThumb');document.addEventListener('dblclick',e=>{if(isProductImage(e))e.preventDefault()},{passive:false});document.addEventListener('touchend',e=>{if(!isProductImage(e))return;const now=Date.now();if(now-lastProductImageTap<350)e.preventDefault();lastProductImageTap=now},{passive:false})})();

/* Bottom navigation body dock iOS V2 */
(()=>{const getNav=()=>document.querySelector('nav.bottom');const getApp=()=>document.getElementById('app');function syncBottomDock(){const n=getNav(),a=getApp();if(!n||!a)return;if(n.parentElement!==document.body)document.body.appendChild(n);const visible=!a.classList.contains('hide')&&!document.body.classList.contains('adminMode');document.body.classList.toggle('shopClientNavVisible',visible)}function bootBottomDock(){syncBottomDock();const a=getApp();if(a)new MutationObserver(syncBottomDock).observe(a,{attributes:true,attributeFilter:['class']});new MutationObserver(syncBottomDock).observe(document.body,{attributes:true,attributeFilter:['class']});window.addEventListener('pageshow',syncBottomDock);window.addEventListener('orientationchange',()=>setTimeout(syncBottomDock,120))}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(bootBottomDock,0),{once:true});else setTimeout(bootBottomDock,0)})();

/* Bottom cart count badge V6 */
(()=>{let lastCartBadgeCount=-1;function syncCartBadge(){const b=document.getElementById("n-cart");if(!b)return;b.classList.add("cartNavButton");let badge=b.querySelector(".cartCountBadge");if(!badge){badge=document.createElement("span");badge.className="cartCountBadge";badge.setAttribute("aria-label","Itens no carrinho");b.appendChild(badge)}const count=Object.values(cart||{}).reduce((sum,q)=>sum+Math.max(0,Number(q)||0),0);if(count<=0){badge.style.display="none";badge.textContent=""}else{badge.style.display="grid";badge.textContent=count>99?"99+":String(count);if(lastCartBadgeCount>=0&&count!==lastCartBadgeCount){badge.classList.remove("cartBadgePulse");void badge.offsetWidth;badge.classList.add("cartBadgePulse")}}lastCartBadgeCount=count}const renderCartBeforeBadge=renderCart;renderCart=function(){renderCartBeforeBadge();syncCartBadge()};window.syncCartBadge=syncCartBadge;if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>setTimeout(syncCartBadge,0),{once:true});else setTimeout(syncCartBadge,0)})();

/* Professional stock admin V7 */
(()=>{let adminStockData={products:[],movements:[],total_skus:0,total_units:0,inventory_cost:0,inventory_sale_value:0,low_stock:0,out_of_stock:0};
function ensureStockAdminUI(){const nav=document.querySelector('#side .nav');if(nav&&!nav.querySelector('[data-p="stock"]')){const b=document.createElement('button');b.dataset.p='stock';b.innerHTML='📊 Estoque';b.onclick=()=>adminPage('stock');const prod=nav.querySelector('[data-p="products"]');prod?.after(b)}const content=document.querySelector('.adminContent');if(content&&!document.getElementById('a-stock')){const p=document.createElement('div');p.id='a-stock';p.className='ap';content.appendChild(p)}if(!document.getElementById('stockMoveModal')){const m=document.createElement('div');m.id='stockMoveModal';m.className='modal';m.innerHTML=`<div class="modalBox stockMoveBox"><div class="modalHead"><div><div class="mut">MOVIMENTAÇÃO DE ESTOQUE</div><h2 id="stockMoveTitle">Produto</h2></div><button class="btn" onclick="closeM('stockMoveModal')">✕</button></div><input id="stockMoveProductId" type="hidden"><div class="stockCurrentBox"><span>Estoque atual</span><strong id="stockMoveCurrent">0</strong></div><div class="two accountForm stockMoveForm"><select id="stockMoveAction" class="field full" onchange="stockMoveActionChanged()"><option value="entry">Entrada de mercadoria</option><option value="exit">Saída manual</option><option value="set">Definir estoque físico</option></select><input id="stockMoveQty" class="field" type="number" min="0" step="1" inputmode="numeric" placeholder="Quantidade"><input id="stockMoveCost" class="field" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Custo unitário (opcional)"><input id="stockMoveReason" class="field full" placeholder="Motivo / observação"><div class="stockMinEditor full"><div><b>Estoque mínimo</b><small>Alerta quando atingir este nível</small></div><input id="stockMoveMin" class="field" type="number" min="0" step="1" inputmode="numeric"><button class="btn" onclick="saveStockMinimum()">Salvar mínimo</button></div></div><button id="stockMoveSave" class="btn red saveWide" onclick="saveStockMovement()">Registrar movimentação</button></div>`;document.body.appendChild(m)}}
function stockStateLabel(x){return x.stock_status==='out'?['Sem estoque','out']:x.stock_status==='low'?['Estoque baixo','low']:['Normal','ok']}function stockMovementLabel(t){return ({opening_balance:'Saldo inicial',entry:'Entrada',exit:'Saída',adjustment:'Ajuste',sale:'Venda',cancellation:'Cancelamento',reactivation:'Reativação'})[t]||t}function stockDeltaText(n){n=Number(n)||0;return `${n>0?'+':''}${n}`}
window.loadAdminStock=async function(){ensureStockAdminUI();if(!adm.ok)return;const page=document.getElementById('a-stock');if(page)page.innerHTML='<div class="stockLoading">Carregando controle de estoque...</div>';try{adminStockData=await api('/rest/v1/rpc/get_admin_stock_dashboard_v1',{method:'POST',body:JSON.stringify({p_limit:300})})||adminStockData;renderAdminStock()}catch(e){if(page)page.innerHTML=`<div class="card"><b>Não foi possível carregar o estoque</b><p class="mut">${esc(e.message)}</p></div>`}};
window.renderAdminStock=function(){ensureStockAdminUI();const d=adminStockData||{},page=document.getElementById('a-stock');if(!page)return;page.innerHTML=`<div class="stockHead"><div><div class="mut">GESTÃO DE MERCADORIA</div><h2>Controle de estoque</h2><p>Entradas, saídas, contagem física, estoque mínimo e histórico em um só lugar.</p></div><button class="btn" onclick="loadAdminStock()">↻ Atualizar</button></div><div class="stockKpis"><div class="stockKpi"><small>Produtos ativos</small><strong>${Number(d.total_skus)||0}</strong><span>SKUs</span></div><div class="stockKpi"><small>Unidades em estoque</small><strong>${Number(d.total_units)||0}</strong><span>unidades</span></div><div class="stockKpi"><small>Valor em custo</small><strong>${money(d.inventory_cost||0)}</strong><span>capital em estoque</span></div><div class="stockKpi"><small>Valor potencial</small><strong>${money(d.inventory_sale_value||0)}</strong><span>preço de venda</span></div><div class="stockKpi warn"><small>Estoque baixo</small><strong>${Number(d.low_stock)||0}</strong><span>abaixo do mínimo</span></div><div class="stockKpi danger"><small>Sem estoque</small><strong>${Number(d.out_of_stock)||0}</strong><span>produtos zerados</span></div></div><div class="stockPanel"><div class="stockToolbar"><input id="stockSearch" class="field" placeholder="Buscar produto, SKU ou marca" oninput="filterAdminStock()"><select id="stockStatusFilter" class="field" onchange="filterAdminStock()"><option value="all">Todos os estoques</option><option value="low">Estoque baixo</option><option value="out">Sem estoque</option><option value="ok">Estoque normal</option></select></div><div id="stockProductRows" class="stockProductRows"></div></div><div class="stockPanel"><div class="stockSectionTitle"><div><h3>Histórico de movimentações</h3><p>Últimas entradas, vendas, saídas, ajustes e devoluções.</p></div></div><div id="stockMovementRows" class="stockMovementRows"></div></div>`;filterAdminStock();renderStockMovements()};
window.filterAdminStock=function(){const q=(document.getElementById('stockSearch')?.value||'').trim().toLowerCase(),st=document.getElementById('stockStatusFilter')?.value||'all';let a=[...(adminStockData.products||[])];if(q)a=a.filter(x=>`${x.name||''} ${x.sku||''} ${x.brand||''}`.toLowerCase().includes(q));if(st!=='all')a=a.filter(x=>x.stock_status===st);const el=document.getElementById('stockProductRows');if(!el)return;el.innerHTML=a.map(x=>{const [lab,cls]=stockStateLabel(x);return `<div class="stockRow ${cls}"><div class="stockProduct"><div class="stockThumb">${x.image_url?`<img src="${esc(x.image_url)}" alt="">`:'📦'}</div><div><b>${esc(x.name)}</b><small>${esc(x.sku||'')} ${x.brand?`• ${esc(x.brand)}`:''}</small></div></div><div class="stockQty"><small>Atual</small><strong>${Number(x.stock_qty)||0}</strong><em>Mín. ${Number(x.min_stock_qty)||0}</em></div><div class="stockMoney"><small>Custo</small><b>${money(x.cost_price||0)}</b><span>Venda ${money(x.sale_price||0)}</span></div><span class="stockState ${cls}">${lab}</span><button class="btn red" onclick="openStockMove('${x.id}')">Movimentar</button></div>`}).join('')||'<div class="stockEmpty">Nenhum produto encontrado.</div>'};
function renderStockMovements(){const el=document.getElementById('stockMovementRows');if(!el)return;const a=adminStockData.movements||[];el.innerHTML=a.map(m=>`<div class="stockMovement"><div class="stockMovementIcon ${Number(m.delta)>0?'in':Number(m.delta)<0?'out':'neutral'}">${Number(m.delta)>0?'↑':Number(m.delta)<0?'↓':'•'}</div><div class="stockMovementMain"><b>${esc(m.product_name||'Produto')}</b><small>${stockMovementLabel(m.movement_type)}${m.order_number?` • Pedido #${m.order_number}`:''}${m.reason?` • ${esc(m.reason)}`:''}</small></div><div class="stockMovementQty ${Number(m.delta)>0?'in':Number(m.delta)<0?'out':''}">${stockDeltaText(m.delta)}</div><div class="stockMovementAfter"><small>Saldo</small><b>${Number(m.after_qty)||0}</b></div><time>${new Date(m.created_at).toLocaleString('pt-BR')}</time></div>`).join('')||'<div class="stockEmpty">Ainda não há movimentações.</div>'}
window.openStockMove=function(id){ensureStockAdminUI();const x=(adminStockData.products||[]).find(p=>p.id===id);if(!x)return toast('Produto não encontrado');document.getElementById('stockMoveProductId').value=id;document.getElementById('stockMoveTitle').textContent=x.name;document.getElementById('stockMoveCurrent').textContent=Number(x.stock_qty)||0;document.getElementById('stockMoveAction').value='entry';document.getElementById('stockMoveQty').value='1';document.getElementById('stockMoveCost').value=x.cost_price||'';document.getElementById('stockMoveReason').value='';document.getElementById('stockMoveMin').value=Number(x.min_stock_qty)||0;stockMoveActionChanged();document.getElementById('stockMoveModal').classList.add('on')};
window.stockMoveActionChanged=function(){const a=document.getElementById('stockMoveAction')?.value,q=document.getElementById('stockMoveQty'),c=document.getElementById('stockMoveCost'),current=Number(document.getElementById('stockMoveCurrent')?.textContent)||0;if(!q||!c)return;if(a==='set'){q.value=String(current);q.placeholder='Novo saldo físico';c.placeholder='Novo custo (opcional)'}else{if(Number(q.value)<=0)q.value='1';q.placeholder='Quantidade';c.placeholder=a==='entry'?'Custo unitário (opcional)':'Custo (opcional)'}};
window.saveStockMinimum=async function(){const id=document.getElementById('stockMoveProductId')?.value,min=Math.floor(Number(document.getElementById('stockMoveMin')?.value));if(!id||!Number.isFinite(min)||min<0)return toast('Informe um estoque mínimo válido');try{await api('/rest/v1/rpc/admin_set_stock_min_v1',{method:'POST',body:JSON.stringify({p_product_id:id,p_min_qty:min})});const x=(adminStockData.products||[]).find(p=>p.id===id);if(x)x.min_stock_qty=min;toast('Estoque mínimo salvo');await loadAdminStock()}catch(e){toast(e.message)}};
window.saveStockMovement=async function(){const id=document.getElementById('stockMoveProductId')?.value,action=document.getElementById('stockMoveAction')?.value,qty=Math.floor(Number(document.getElementById('stockMoveQty')?.value)),cost=Number(document.getElementById('stockMoveCost')?.value),reason=document.getElementById('stockMoveReason')?.value||'',btn=document.getElementById('stockMoveSave');if(!id||!Number.isFinite(qty)||qty<0||(action!=='set'&&qty<=0))return toast('Informe uma quantidade válida');try{btn.disabled=true;btn.textContent='Salvando...';const r=await api('/rest/v1/rpc/admin_stock_move_v1',{method:'POST',body:JSON.stringify({p_product_id:id,p_action:action,p_quantity:qty,p_unit_cost:Number.isFinite(cost)&&cost>0?cost:null,p_reason:reason})});const p0=adm.products?.find(p=>p.id===id);if(p0){p0.stock_qty=r.after_qty;p0.cost_price=r.cost_price}renderAdminProducts?.();closeM('stockMoveModal');await Promise.all([loadAdminStock(),loadCat()]);toast('Movimentação registrada')}catch(e){toast(({INSUFFICIENT_STOCK:'Estoque insuficiente',NO_STOCK_CHANGE:'O estoque já está nessa quantidade',INVALID_QUANTITY:'Quantidade inválida'})[e.message]||e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Registrar movimentação'}}};
const stockAdminPageBase=adminPage;adminPage=function(x){ensureStockAdminUI();stockAdminPageBase(x);if(x==='stock'){document.getElementById('adminTitle').textContent='Controle de estoque';loadAdminStock()}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(ensureStockAdminUI,0),{once:true});else setTimeout(ensureStockAdminUI,0)})();

/* Product photo quick tools V8 */
(()=>{const PHOTO_EDGE=U+'/functions/v1/product-image-lookup';
function photoExtType(file){const t=(file?.type||'').toLowerCase();return t.includes('png')?'png':t.includes('webp')?'webp':t.includes('avif')?'avif':'jpg'}
async function normalizeProductPhoto(file){if(!file||!String(file.type||'').startsWith('image/'))throw Error('Selecione uma imagem válida');if(file.size>12*1024*1024)throw Error('A imagem é muito grande. Use até 12 MB.');try{const url=URL.createObjectURL(file),img=new Image();img.src=url;await img.decode();const max=1800,scale=Math.min(1,max/Math.max(img.naturalWidth||1,img.naturalHeight||1));const w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);URL.revokeObjectURL(url);const blob=await new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(Error('Não foi possível preparar a imagem')),'image/jpeg',.9));return new File([blob],(file.name||'produto').replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'})}catch(e){if(['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))return file;throw Error('Formato de imagem não suportado. Use JPG, PNG ou WEBP.')}}
async function uploadProductPhotoFile(file){if(!s?.access_token)throw Error('Faça login novamente');file=await normalizeProductPhoto(file);const sku=(document.getElementById('psku')?.value||'produto').replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,50)||'produto';const ext=photoExtType(file),path=`uploads/${sku}-${Date.now()}-${crypto.randomUUID()}.${ext}`;const r=await fetch(`${U}/storage/v1/object/product-images/${path}`,{method:'POST',headers:{apikey:K,Authorization:'Bearer '+s.access_token,'Content-Type':file.type,'x-upsert':'false'},body:file});if(!r.ok){let t=await r.text();throw Error(t||'Falha ao enviar a foto')}return `${U}/storage/v1/object/public/product-images/${path}`}
function addGalleryUrl(url){const g=document.getElementById('pgallery');if(!g||!url)return;const a=g.value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!a.includes(url))a.push(url);g.value=a.join('\n');syncProductPhotoPreview()}
function syncProductPhotoPreview(){const p=document.getElementById('productPhotoPreview'),u=(document.getElementById('pimg')?.value||'').trim();if(!p)return;p.innerHTML=u?`<img src="${esc(u)}" alt="Prévia"><span>Imagem principal</span>`:'<div class="productPhotoEmpty">📷<small>Nenhuma foto principal</small></div>'}
function ensureProductPhotoTools(){const pimg=document.getElementById('pimg');if(!pimg||document.getElementById('productPhotoTools'))return;const box=document.createElement('div');box.id='productPhotoTools';box.className='productPhotoTools full';box.innerHTML=`<div id="productPhotoPreview" class="productPhotoPreview"></div><div class="productPhotoQuick"><button type="button" class="btn red" onclick="document.getElementById('productMainFile').click()">📷 Adicionar foto</button><button type="button" class="btn" onclick="searchProductPhotos()">🔎 Buscar pelo código</button><button type="button" class="btn" onclick="document.getElementById('productGalleryFile').click()">＋ Foto na galeria</button></div><input id="productMainFile" type="file" accept="image/*" hidden onchange="uploadMainProductPhoto(this)"><input id="productGalleryFile" type="file" accept="image/*" hidden onchange="uploadGalleryProductPhoto(this)"><div id="productPhotoStatus" class="productPhotoStatus"></div><div id="productPhotoResults" class="productPhotoResults"></div>`;pimg.after(box);pimg.addEventListener('input',syncProductPhotoPreview);syncProductPhotoPreview()}
window.uploadMainProductPhoto=async function(input){const f=input?.files?.[0];if(!f)return;const st=document.getElementById('productPhotoStatus');try{if(st)st.textContent='Enviando e preparando foto...';const url=await uploadProductPhotoFile(f);document.getElementById('pimg').value=url;syncProductPhotoPreview();toast('Foto principal adicionada')}catch(e){toast(e.message)}finally{input.value='';if(st)st.textContent=''}};
window.uploadGalleryProductPhoto=async function(input){const f=input?.files?.[0];if(!f)return;const st=document.getElementById('productPhotoStatus');try{if(st)st.textContent='Enviando foto para a galeria...';const url=await uploadProductPhotoFile(f);addGalleryUrl(url);toast('Foto adicionada à galeria')}catch(e){toast(e.message)}finally{input.value='';if(st)st.textContent=''}};
async function photoEdge(body){const r=await fetch(PHOTO_EDGE,{method:'POST',headers:{apikey:K,Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'},body:JSON.stringify(body)}),t=await r.text();let d;try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw Error(d?.error==='ADMIN_REQUIRED'?'Acesso de administrador necessário':d?.message||d?.error||'Falha na busca de fotos');return d}
window.searchProductPhotos=async function(){ensureProductPhotoTools();const code=(document.getElementById('psku')?.value||'').trim(),name=(document.getElementById('pn')?.value||'').trim(),brand=(document.getElementById('pb')?.value||'').trim(),st=document.getElementById('productPhotoStatus'),out=document.getElementById('productPhotoResults');if(!code&&!name)return toast('Informe o código/SKU ou o nome do produto');try{if(st)st.textContent='Buscando fotos pelo código do produto...';if(out)out.innerHTML='';const d=await photoEdge({mode:'search',code,name,brand}),found=(d.candidates||[]).slice(0,6);if(!found.length){if(st)st.textContent='Nenhuma foto encontrada automaticamente. Você pode usar Adicionar foto.';return}if(st)st.textContent=`${found.length} opção(ões) encontrada(s). Preparando as imagens...`;const prepared=[];for(const c of found){try{const imp=await photoEdge({mode:'import',url:c.url,code:code||name});if(imp?.url)prepared.push({...c,stored_url:imp.url})}catch{}}if(!prepared.length){if(st)st.textContent='As fotos foram encontradas, mas não puderam ser importadas. Use Adicionar foto.';return}if(st)st.textContent='Escolha a melhor foto:';out.innerHTML=prepared.map((c,i)=>`<div class="productPhotoResult"><div class="productPhotoResultImg"><img src="${esc(c.stored_url)}" alt="${esc(c.title||'Produto')}"></div><div class="productPhotoResultInfo"><b>${esc(c.title||name||'Produto')}</b><small>${esc([c.brand,c.model,c.ean].filter(Boolean).join(' • '))}</small><div><button type="button" class="btn red" onclick="useFoundProductPhoto(${i},false)">Usar principal</button><button type="button" class="btn" onclick="useFoundProductPhoto(${i},true)">+ Galeria</button></div></div></div>`).join('');window.__foundProductPhotos=prepared}catch(e){if(st)st.textContent='';toast(e.message)}};
window.useFoundProductPhoto=function(i,toGallery){const c=window.__foundProductPhotos?.[i];if(!c?.stored_url)return;if(toGallery)addGalleryUrl(c.stored_url);else{document.getElementById('pimg').value=c.stored_url;syncProductPhotoPreview()}if(!document.getElementById('pn').value&&c.title)document.getElementById('pn').value=c.title;if(!document.getElementById('pb').value&&c.brand)document.getElementById('pb').value=c.brand;toast(toGallery?'Foto adicionada à galeria':'Foto principal selecionada')};
const editProductPhotoBase=editProduct;editProduct=function(id=''){editProductPhotoBase(id);setTimeout(()=>{ensureProductPhotoTools();syncProductPhotoPreview();const r=document.getElementById('productPhotoResults'),st=document.getElementById('productPhotoStatus');if(r)r.innerHTML='';if(st)st.textContent='';window.__foundProductPhotos=[]},0)};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(ensureProductPhotoTools,0),{once:true});else setTimeout(ensureProductPhotoTools,0)})();

/* Home brand bubbles V14 */
(()=>{const norm=v=>String(v||'').trim();const key=v=>norm(v).toLocaleUpperCase('pt-BR');const preferred=['AGOLD','KAPBOM','ELETROMEX','APPLE'];function getHomeBrands(){const map=new Map();(cat||[]).forEach(x=>{const brand=norm(x?.brand);if(!brand)return;const k=key(brand),cur=map.get(k);if(cur)cur.count++;else map.set(k,{brand,count:1})});return [...map.values()].sort((a,b)=>{const ai=preferred.indexOf(key(a.brand)),bi=preferred.indexOf(key(b.brand));if(ai>=0||bi>=0){if(ai<0)return 1;if(bi<0)return -1;if(ai!==bi)return ai-bi}return b.count-a.count||a.brand.localeCompare(b.brand,'pt-BR')})}function paintHomeBrandBubbles(){const el=document.getElementById('homeBrandBubbles');if(!el)return;const brands=getHomeBrands();el.innerHTML=brands.map(({brand})=>`<button class="homeBrandBubble" onclick="openHomeBrand('${encodeURIComponent(brand)}')" aria-label="Ver produtos ${esc(brand)}"><span><b>${esc(brand)}</b></span><small>${esc(brand)}</small></button>`).join('')+`<button class="homeBrandBubble all" onclick="openAllHomeBrands()" aria-label="Ver todas as marcas"><span><b>＋</b></span><small>Ver todas</small></button>`}window.openHomeBrand=function(raw){const brand=decodeURIComponent(raw);go('stock');setTimeout(()=>{const f=document.getElementById('brandFilter');if(f){f.value=brand;renderProducts()}},80)};window.openAllHomeBrands=function(){go('stock');setTimeout(()=>{const f=document.getElementById('brandFilter');if(f){f.value='';renderProducts()}},80)};const loadCatBeforeBrandBubbles=loadCat;loadCat=async function(){await loadCatBeforeBrandBubbles();paintHomeBrandBubbles()};window.paintHomeBrandBubbles=paintHomeBrandBubbles;if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(paintHomeBrandBubbles,0),{once:true});else setTimeout(paintHomeBrandBubbles,0)})();

/* User supplied brand logos V16 */
(()=>{let brandLogoData={};let brandLogosLoaded=false;const canon=v=>String(v||'').trim().toLocaleUpperCase('pt-BR').replace(/’/g,"'");const logoKey=v=>{const k=canon(v);if(k==="A'GOLD"||k==='AGOLD')return 'AGOLD';if(k==='B-MAX')return 'BMAX';if(k==="H'MASTON")return 'HMASTON';return k};const preferred=['AGOLD','KAPBOM','ELETROMEX','ALTOMEX','APPLE','STANLEY','BMAX','HOLDA','LEHMOX','HMASTON','SUMEXR','DAPON','IT-BLUE'];async function loadBrandLogosV16(){if(brandLogosLoaded)return brandLogoData;try{const rows=await api('/rest/v1/brand_logo_assets?select=brand_key,image_data&order=brand_key.asc');brandLogoData=Object.fromEntries((rows||[]).map(r=>[String(r.brand_key||'').toUpperCase(),r.image_data]));brandLogosLoaded=true}catch(e){console.warn('brand logos',e.message)}return brandLogoData}function homeBrandsV16(){const map=new Map();(cat||[]).forEach(x=>{const brand=String(x?.brand||'').trim();if(!brand)return;const k=logoKey(brand),cur=map.get(k);if(cur)cur.count++;else map.set(k,{brand,count:1})});return [...map.values()].sort((a,b)=>{const ai=preferred.indexOf(logoKey(a.brand)),bi=preferred.indexOf(logoKey(b.brand));if(ai>=0||bi>=0){if(ai<0)return 1;if(bi<0)return -1;if(ai!==bi)return ai-bi}return b.count-a.count||a.brand.localeCompare(b.brand,'pt-BR')})}function fallbackText(brand){return canon(brand).replace(/[^A-Z0-9]/g,'').slice(0,5)||'MARCA'}function paintV16(){const el=document.getElementById('homeBrandBubbles');if(!el)return;el.innerHTML=homeBrandsV16().map(({brand})=>{const logo=brandLogoData[logoKey(brand)]||'';return `<button class="homeBrandBubble logoBubble userLogo" onclick="openHomeBrand('${encodeURIComponent(brand)}')" aria-label="Ver produtos ${esc(brand)}"><span>${logo?`<img src="${logo}" alt="Logo ${esc(brand)}">`:''}<b class="brandLogoFallback" style="${logo?'display:none':''}">${esc(fallbackText(brand))}</b></span><small>${esc(brand)}</small></button>`}).join('')+`<button class="homeBrandBubble all" onclick="openAllHomeBrands()" aria-label="Ver todas as marcas"><span><b>＋</b></span><small>Ver todas</small></button>`;el.scrollLeft=0}window.paintHomeBrandBubbles=paintV16;const loadCatBeforeUserLogos=loadCat;loadCat=async function(){await loadCatBeforeUserLogos();await loadBrandLogosV16();paintV16()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>loadBrandLogosV16().then(paintV16),40),{once:true});else setTimeout(()=>loadBrandLogosV16().then(paintV16),40)})();

/* Product detail premium V19 */
(()=>{function detailImagesV19(x){return galleryOf(x)}function detailMetaV19(x){const items=[];if(x.brand)items.push(`<span class="detailMetaPill brand">${esc(x.brand)}</span>`);if(x.sku)items.push(`<span class="detailMetaPill">SKU ${esc(x.sku)}</span>`);if(x.category_name)items.push(`<span class="detailMetaPill">${esc(x.category_name)}</span>`);return items.join('')}function tierSavingsV19(x,t){const base=+x.sale_price||0,price=+t.price||0;if(base<=0||price<=0||price>=base)return '';const pct=Math.round((base-price)/base*100);return pct>0?`<em>Economize ${pct}%</em>`:''}function paintDetailGalleryV19(){const imgs=detailImagesV19(detailProduct);const g=document.getElementById('detailGallery');if(!g)return;g.innerHTML=imgs.map((u,i)=>`<button class="detailThumb premiumDetailThumb ${u===detailImage?'on':''}" onclick="setDetailImage('${encodeURIComponent(u)}')" aria-label="Ver foto ${i+1}"><img src="${esc(u)}" alt="Foto ${i+1}"><span>${i+1}</span></button>`).join('')}function paintDetailStockV19(x){const out=+x.stock_qty<=0,stock=Math.max(0,+x.stock_qty||0),min=Math.max(1,+x.min_per_customer||1);const stockText=out?'Sem estoque no momento':`${stock} unidades disponíveis`;return `<div class="detailAvailability ${out?'out':'ok'}"><div class="detailAvailabilityIcon">${out?'!':'✓'}</div><div><small>DISPONIBILIDADE</small><b>${esc(stockText)}</b>${!out&&min>1?`<span>Pedido mínimo: ${min} un.</span>`:''}</div></div>${x.warranty_text?`<div class="detailWarranty"><span>◆</span><div><small>GARANTIA</small><b>${esc(x.warranty_text)}</b></div></div>`:''}`}function paintDetailProfitV19(x,unit){const pd=profitData(x,unit);const el=document.getElementById('detailProfit');if(!el)return;if(pd)el.innerHTML=`<div class="detailProfitIcon">↗</div><div><small>POTENCIAL DE REVENDA</small><b>${money(pd.profit)} de lucro por unidade</b><span>Venda sugerida ${money(pd.ref)} • margem potencial ${pd.margin.toFixed(0)}%</span></div>`;else el.innerHTML='<div class="detailProfitIcon muted">↗</div><div><small>POTENCIAL DE REVENDA</small><b>Preço de atacado competitivo</b><span>Venda sugerida não informada para este produto.</span></div>'}
window.openProductDetail=function(id){const x=cat.find(p=>p.id===id);if(!x)return;detailProduct=x;const imgs=detailImagesV19(x);detailImage=imgs[0]||'';const name=document.getElementById('detailName'),kicker=document.getElementById('detailKicker'),meta=document.getElementById('detailMeta');if(name)name.textContent=x.name;if(kicker)kicker.textContent='DETALHES DO PRODUTO';if(meta)meta.innerHTML=detailMetaV19(x);renderDetailImage();paintDetailGalleryV19();const qty=Math.max(+x.min_per_customer||1,1),qtyEl=document.getElementById('detailQty');if(qtyEl){qtyEl.value=qty;qtyEl.min=qty;qtyEl.max=Math.max(qty,+x.stock_qty||qty);qtyEl.disabled=+x.stock_qty<=0}const ts=tiersOf(x),tiersEl=document.getElementById('detailTiers');if(tiersEl)tiersEl.innerHTML=`<div class="detailTierHeader"><div><small>CONDIÇÃO DE ATACADO</small><b>${ts.length>1?'Compre mais, pague menos':'Preço para lojista'}</b></div>${ts.length>1?'<span>Melhor preço automático</span>':''}</div>`+(ts.length?ts.map(t=>`<div class="detailTier premiumDetailTier" data-min="${t.min}"><div><span>A partir de</span><b>${t.min} un.</b></div><strong>${money(t.price)}<small>/un.</small></strong>${tierSavingsV19(x,t)}</div>`).join(''):`<div class="detailTier premiumDetailTier" data-min="1"><div><span>Preço de atacado</span><b>1 un.</b></div><strong>${money(x.sale_price)}<small>/un.</small></strong></div>`);const stockEl=document.getElementById('detailStock');if(stockEl)stockEl.innerHTML=paintDetailStockV19(x);const desc=document.getElementById('detailDescription');if(desc)desc.innerHTML=x.description?`<h3><span>01</span> Sobre o produto</h3><p>${esc(x.description).replace(/\\n/g,'<br>')}</p>`:'';const sp=x.specs&&typeof x.specs==='object'?Object.entries(x.specs):[],spec=document.getElementById('detailSpecs');if(spec)spec.innerHTML=sp.length?`<h3><span>02</span> Especificações</h3><div class="specGrid premiumSpecGrid">${sp.map(([k,v])=>`<div class="specItem"><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}</div>`:'';const addBtn=document.querySelector('#productDetailModal .detailBuy .btn.red');if(addBtn){addBtn.disabled=+x.stock_qty<=0;addBtn.textContent=+x.stock_qty<=0?'Produto sem estoque':'Adicionar ao carrinho'}updateDetailPrice();document.getElementById('productDetailModal')?.classList.add('on')};
window.setDetailImage=function(u){detailImage=decodeURIComponent(u);renderDetailImage();paintDetailGalleryV19()};window.updateDetailPrice=function(){if(!detailProduct)return;const min=Math.max(1,+detailProduct.min_per_customer||1),stock=Math.max(0,+detailProduct.stock_qty||0),qtyEl=document.getElementById('detailQty');let q=Math.max(+qtyEl?.value||min,min);if(stock>0&&q>stock){q=stock;if(qtyEl)qtyEl.value=q}const unit=unitPrice(detailProduct,q),total=unit*q,priceEl=document.getElementById('detailPrice');if(priceEl)priceEl.innerHTML=`<div class="detailPriceLabel">PREÇO NO ATACADO</div><div class="detailPriceMain"><strong>${money(unit)}</strong><span>/ unidade</span></div><div class="detailPriceTotal"><span>Total para ${q} un.</span><b>${money(total)}</b></div>`;const activeMin=Math.max(...tiersOf(detailProduct).filter(t=>q>=t.min).map(t=>t.min),0);document.querySelectorAll('#detailTiers .detailTier[data-min]').forEach(el=>el.classList.toggle('on',+el.dataset.min===(activeMin||1)));paintDetailProfitV19(detailProduct,unit)};const addFromDetailBeforeV19=window.addFromDetail;window.addFromDetail=function(){if(!detailProduct||+detailProduct.stock_qty<=0)return toast('Produto sem estoque');return addFromDetailBeforeV19()}})();

/* Premium cart V20 */
(()=>{const renderCartBeforePremiumV20=renderCart;function cartLinesV20(){return Object.entries(cart||{}).map(([id,q])=>{const p=cat.find(x=>x.id===id);if(!p)return null;const qty=Math.max(1,Math.floor(Number(q)||1));const min=Math.max(1,Number(p.min_per_customer)||1);const stock=Math.max(0,Number(p.stock_qty)||0);const max=Math.max(min,stock);const unit=typeof unitPrice==='function'?unitPrice(p,qty):(+p.sale_price||0);return {p,qty,min,max,unit,total:unit*qty}}).filter(Boolean)}function ensurePremiumCartShellV20(){const section=document.getElementById('cart'),card=section?.querySelector(':scope > .card');if(!section||!card)return;section.classList.add('premiumCartScreen');card.classList.add('premiumCartCard');const oldH=card.querySelector(':scope > h2');if(oldH&&!card.querySelector('.premiumCartHead')){const head=document.createElement('div');head.className='premiumCartHead';head.innerHTML=`<div><div class="mut">SEU PEDIDO</div><h2>Carrinho</h2><p>Revise os produtos e quantidades antes de finalizar.</p></div><span id="premiumCartCount" class="premiumCartCount">0 itens</span>`;oldH.replaceWith(head)}const checkoutBtn=[...card.querySelectorAll(':scope > button')].find(b=>String(b.getAttribute('onclick')||'').includes('checkout()'));if(checkoutBtn){checkoutBtn.classList.add('premiumCheckoutBtn');checkoutBtn.innerHTML='<span>Finalizar pedido</span><b>→</b>'}}
window.cartStepV20=function(id,delta){const p=cat.find(x=>x.id===id);if(!p)return;const min=Math.max(1,Number(p.min_per_customer)||1),stock=Math.max(0,Number(p.stock_qty)||0),max=Math.max(min,stock);const current=Math.max(min,Math.floor(Number(cart[id])||min));const next=Math.max(min,Math.min(max,current+Number(delta||0)));cart[id]=next;localStorage.setItem(CK,JSON.stringify(cart));renderCart()};window.cartQtyV20=function(id,input){const p=cat.find(x=>x.id===id);if(!p||!input)return;const min=Math.max(1,Number(p.min_per_customer)||1),stock=Math.max(0,Number(p.stock_qty)||0),max=Math.max(min,stock);let n=Math.floor(Number(input.value));if(!Number.isFinite(n)||n<min)n=min;if(n>max){n=max;toast(`Estoque máximo: ${max}`)}cart[id]=n;input.value=String(n);localStorage.setItem(CK,JSON.stringify(cart));renderCart()};window.cartRemoveV20=function(id){delete cart[id];localStorage.setItem(CK,JSON.stringify(cart));renderCart();toast('Produto removido do carrinho')};window.continueShoppingV20=function(){go('stock')};
function paintPremiumCartV20(){ensurePremiumCartShellV20();const rows=document.getElementById('cartRows'),totalEl=document.getElementById('cartTotal');if(!rows||!totalEl)return;const lines=cartLinesV20(),units=lines.reduce((s,x)=>s+x.qty,0),subtotal=lines.reduce((s,x)=>s+x.total,0);const count=document.getElementById('premiumCartCount');if(count)count.textContent=`${units} ${units===1?'item':'itens'}`;if(!lines.length){rows.innerHTML=`<div class="premiumCartEmpty"><div class="premiumCartEmptyIcon">🛒</div><h3>Seu carrinho está vazio</h3><p>Escolha produtos do catálogo para montar seu pedido de atacado.</p><button class="btn red" onclick="continueShoppingV20()">Ver catálogo</button></div>`;totalEl.innerHTML='';const b=document.querySelector('#cart .premiumCheckoutBtn');if(b)b.disabled=true;return}rows.innerHTML=lines.map(({p,qty,min,max,unit,total})=>`<div class="premiumCartRow"><button class="premiumCartImage" onclick="openProductDetail('${p.id}')">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}">`:'<span>📦</span>'}</button><div class="premiumCartProduct"><div class="premiumCartMeta"><span>${esc(p.brand||p.category_name||'Shop Importadora')}</span>${p.sku?`<small>SKU ${esc(p.sku)}</small>`:''}</div><b class="premiumCartName" onclick="openProductDetail('${p.id}')">${esc(p.name)}</b><div class="premiumCartUnit">${money(unit)} <small>/ un.</small>${hasRealTiers(p)?'<em>Preço por quantidade aplicado</em>':''}</div><div class="premiumCartControls"><button onclick="cartStepV20('${p.id}',-1)" ${qty<=min?'disabled':''}>−</button><input type="number" min="${min}" max="${max}" value="${qty}" inputmode="numeric" onchange="cartQtyV20('${p.id}',this)" aria-label="Quantidade"><button onclick="cartStepV20('${p.id}',1)" ${qty>=max?'disabled':''}>+</button><button class="premiumCartRemove" onclick="cartRemoveV20('${p.id}')">Remover</button></div></div><div class="premiumCartLineTotal"><small>Total</small><strong>${money(total)}</strong><span>${qty} un.</span></div></div>`).join('');totalEl.innerHTML=`<div class="premiumCartSummary"><div class="premiumCartSummaryTop"><div><span>Produtos</span><small>${units} ${units===1?'unidade':'unidades'} no carrinho</small></div><strong>${money(subtotal)}</strong></div><div class="premiumCartBenefits"><span>✓ Estoque reservado ao confirmar</span><span>✓ Frete calculado na finalização</span><span>✓ Pagamento via PIX</span></div><div class="premiumCartSubtotal"><div><small>Subtotal estimado</small><span>Frete não incluído</span></div><strong>${money(subtotal)}</strong></div><button class="premiumContinueShopping" onclick="continueShoppingV20()">← Continuar comprando</button></div>`;const b=document.querySelector('#cart .premiumCheckoutBtn');if(b)b.disabled=false}renderCart=function(){renderCartBeforePremiumV20();paintPremiumCartV20()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{ensurePremiumCartShellV20();paintPremiumCartV20()},0),{once:true});else setTimeout(()=>{ensurePremiumCartShellV20();paintPremiumCartV20()},0)})();
